import { describe, expect, test } from "vitest";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { generateDataTs } from "../lib/codegen";
import { countChunkedEntries, planChunking } from "../scripts/chunk-data-ts";
import { domains, lastSynced, models, organizations, years } from "../lib/data";
import type { DataSourceAdapter } from "../lib/types";

/**
 * `lib/data.ts` is generated by `scripts/sync-data.ts` and committed. It used to
 * carry `// @ts-nocheck`, which meant the app's entire 4,307-model dataset was
 * the one file exempt from type-checking.
 *
 * Both the generator and a one-off transform now emit the array as chunks of
 * `Model[]`, which collapses the union TypeScript could not represent. These
 * tests exist because the two must agree: `sync-data.ts` runs a **network sync**
 * and rewrites the file wholesale, so if the generator reverted to a single
 * literal the next sync would silently put `@ts-nocheck` back — or, worse, drop
 * it while emitting the shape that needs it, and the app would stop type-checking.
 *
 * That is not hypothetical: the check cannot be run here, because regenerating
 * requires fetching model data.
 */

// vitest's transform makes `new URL(x, import.meta.url)` unusable, so resolve
// from `import.meta.url` directly.
const APP_DIR = join(dirname(fileURLToPath(import.meta.url)), "..");
const DATA_FILE = join(APP_DIR, "lib/data.ts");

/** A source adapter is only used for the header comment block. */
const sources: DataSourceAdapter[] = [
  {
    id: "test",
    label: "Test",
    count: 0,
    urls: ["https://example.com"],
    models: [],
    mergedAt: "",
  } as unknown as DataSourceAdapter,
];

/**
 * True when the text still carries a `@ts-nocheck` **pragma**.
 *
 * Deliberately not a substring check: the generated header explains *why* the
 * file used to need the pragma, so the string legitimately appears in prose. A
 * substring assertion would fail on that explanation and invite deleting the
 * thing that documents the decision.
 */
function hasNoCheckPragma(text: string): boolean {
  return text
    .split("\n")
    .some((line) => line.trimStart().startsWith("@ts-nocheck"));
}

const STATS = {
  total: 0,
  duplicates: 0,
  sources: {},
} as unknown as Parameters<typeof generateDataTs>[3];

describe("generated data.ts shape", () => {
  test("the committed file carries no @ts-nocheck pragma", () => {
    const source = readFileSync(DATA_FILE, "utf8");
    expect(hasNoCheckPragma(source)).toBe(false);
    // And the reason it is gone is recorded, so the next person does not
    // re-add it without learning why it was there.
    expect(source).toContain("TS2590");
  });

  test("the committed file is chunked, and the chunks concatenate in order", () => {
    const source = readFileSync(DATA_FILE, "utf8");

    // One `const cN: Model[] = [` per chunk, and one spread per chunk in the
    // export. A mismatch between the two counts would drop or duplicate rows.
    const declared = [...source.matchAll(/^const c(\d+): Model\[\] = \[$/gm)].map(
      (m) => Number(m[1])
    );
    expect(declared.length).toBeGreaterThan(1);
    expect(declared).toEqual(
      Array.from({ length: declared.length }, (_, i) => i)
    );

    const exportLine = source
      .split("\n")
      .find((line) => line.startsWith("export const models: Model[] = ["));
    expect(exportLine).toBeDefined();
    const spread = [...(exportLine as string).matchAll(/\.\.\.c(\d+)/g)].map((m) =>
      Number(m[1])
    );
    expect(spread).toEqual(declared);
  });

  test("the runtime data is exactly what the chunks declare", () => {
    // The assertion that actually matters: the app's rendered pages depend on
    // these 4,307 rows. Importing `models` and comparing against the file's own
    // entry count closes the loop that a text-only check leaves open — a chunk
    // that parses but drops or reorders rows passes every `toContain` above and
    // fails only here.
    const source = readFileSync(DATA_FILE, "utf8");
    expect(countChunkedEntries(source)).toBe(models.length);
    expect(models.length).toBeGreaterThan(1000);
  });

  test("the derived collections still match the models they are computed from", () => {
    // `organizations`, `domains` and `years` are `.map`/`.filter` chains over
    // `models` in the same file. Re-chunking moved the array literal but not
    // those chains, so verify they still agree with the rows rather than
    // trusting that the text above them was left alone.
    const sortedUnique = (values: Array<string | number>) =>
      [...new Set(values)].sort((a, b) =>
        String(a) < String(b) ? -1 : String(a) > String(b) ? 1 : 0
      );

    expect(organizations).toEqual(sortedUnique(models.map((m) => m.org)));
    expect(domains).toEqual(
      sortedUnique(
        models
          .filter((m) => m.domain)
          .flatMap((m) => (m.domain as string).split(",").map((d) => d.trim()))
      )
    );
    expect(years).toEqual(
      [...new Set(models.map((m) => new Date(m.date).getFullYear()))].sort(
        (a, b) => b - a
      )
    );

    // A stale `lastSynced` would make the app claim a sync that never happened.
    // It is a plain literal at the end of the generated file, so assert the
    // shape rather than a value that changes on every network sync.
    expect(lastSynced).toMatch(/^\d{4}-\d{2}-\d{2}$/);
  });

  test("generateDataTs emits the same chunked shape, and never @ts-nocheck", () => {
    // The generator and the committed file must agree, or the next network sync
    // reverts this.
    const generated = generateDataTs(
      [
        {
          name: "Test-1",
          date: "2026-01-01",
          org: "Test",
          params: "1B",
          type: "model",
          license: "open",
          desc: "desc",
        },
      ],
      sources,
      "2026-01-01",
      STATS
    );

    expect(hasNoCheckPragma(generated)).toBe(false);
    expect(generated).toContain("const c0: Model[] = [");
    expect(generated).toContain("export const models: Model[] = [...c0].flat();");
  });

  test("a corpus large enough to span several chunks spreads all of them", () => {
    // One entry proves the shape; the chunk boundary is the thing that could
    // silently drop rows, so build past CHUNK_SIZE (250).
    const many = Array.from({ length: 300 }, (_, i) => ({
      name: `Model-${i}`,
      date: "2026-01-01",
      org: "Test",
      params: null,
      type: "model" as const,
      license: "open" as const,
      desc: `desc ${i}`,
    }));

    const generated = generateDataTs(many, sources, "2026-01-01", STATS);

    expect(generated).toContain("const c0: Model[] = [");
    expect(generated).toContain("const c1: Model[] = [");
    expect(generated).not.toContain("const c2: Model[] = [");
    expect(generated).toContain("export const models: Model[] = [...c0, ...c1].flat();");
    // Every entry present, so no row is lost across the boundary.
    for (let i = 0; i < 300; i++) {
      expect(generated).toContain(`name: 'Model-${i}'`);
    }
  });
});

describe("chunk-data-ts transform", () => {
  test("refuses to run on an already-chunked file rather than double-chunking", () => {
    // Running the transform twice must be detectable, not silently idempotent.
    const chunked = readFileSync(DATA_FILE, "utf8");
    expect(() => planChunking(chunked)).toThrow();
  });

  test("produces output with no @ts-nocheck from an input that has one", () => {
    const pragma = "// @ts-nocheck — machine-generated file, types validated by Model interface\n";
    const source = `${pragma}export interface Model { name: string }\n\nexport const models: Model[] = [\n  {\n    name: 'A',\n  },\n  {\n    name: 'B',\n  },\n]\n`;

    const plan = planChunking(source);

    expect(plan.entryCount).toBe(2);
    expect(plan.removedNoCheck).toBe(true);
    expect(hasNoCheckPragma(plan.output)).toBe(false);
    expect(plan.output).toContain("const c0: Model[] = [");
    expect(plan.output).toContain("export const models: Model[] = [...c0].flat();");
  });

  test("keeps entries in order and does not split on braces inside strings", () => {
    // The scanner is hand-rolled because the values contain braces and quotes.
    const source = [
      "export interface Model { name: string }",
      "",
      "export const models: Model[] = [",
      "  {",
      "    name: 'has {brace} and, comma',",
      "  },",
      "  {",
      "    name: 'plain',",
      "  },",
      "]",
      "",
    ].join("\n");

    const plan = planChunking(source);

    expect(plan.entryCount).toBe(2);
    expect(plan.output).toContain("has {brace} and, comma");
    expect(plan.output.indexOf("has {brace}")).toBeLessThan(
      plan.output.indexOf("name: 'plain'")
    );
  });

  test("countChunkedEntries is the inverse of planChunking", () => {
    // The two are the only pair of functions that can disagree about how many
    // rows exist. Feed the transform a known corpus and assert the count comes
    // back unchanged, across a chunk boundary (CHUNK_SIZE is 250).
    const many = Array.from({ length: 300 }, (_, i) => ({
      name: `Model-${i}`,
      date: "2026-01-01",
      org: "Test",
      params: null,
      type: "model" as const,
      license: "open" as const,
      desc: `desc ${i}`,
    }));
    const generated = generateDataTs(many, sources, "2026-01-01", STATS);

    expect(countChunkedEntries(generated)).toBe(300);
  });

  test("countChunkedEntries ignores braces and commas inside string values", () => {
    // Values in this dataset contain braces, quotes and commas. A naive
    // `{`-count or line-count would be wrong here; the scanner is not.
    const source = [
      "export interface Model { name: string }",
      "",
      "const c0: Model[] = [",
      "  {",
      "    name: 'a {b} c, d',",
      "  },",
      "  {",
      "    name: 'plain',",
      "  },",
      "]",
      "",
    ].join("\n");

    expect(countChunkedEntries(source)).toBe(2);
  });

  test("countChunkedEntries throws on a file with no chunks, not a silent 0", () => {
    const source = "export const models: Model[] = [\n  { name: 'A' },\n]\n";
    expect(() => countChunkedEntries(source)).toThrow(/no chunks/i);
  });

  test("reports unbalanced braces instead of writing a truncated file", () => {
    const source = [
      "export interface Model { name: string }",
      "",
      "export const models: Model[] = [",
      "  {",
      "    name: 'unterminated',",
      "]",
      "",
    ].join("\n");

    expect(() => planChunking(source)).toThrow(/unbalanced/i);
  });
});
